theory.code:
zasieg GLOBALNY (globalNote)
  |
  v  (outer() MOZE odczytac globalNote)
funkcja outer() (outerNote)
  |
  v  (inner() MOZE odczytac globalNote ORAZ outerNote)
funkcja inner() (innerNote)

// strzalki dzialaja TYLKO w dol -> w gore (poszukiwanie zmiennej):
// inner widzi innerNote + outerNote + globalNote
// outer widzi outerNote + globalNote (NIE widzi innerNote!)
// kod globalny widzi TYLKO globalNote (NIE widzi outerNote ani innerNote!)

const globalNote = "globalny";

function outer() {
  const outerNote = "zewnętrzny";

  function inner() {
    const innerNote = "wewnętrzny";
    console.log(globalNote); // "globalny" - z zasiegu globalnego
    console.log(outerNote);  // "zewnętrzny" - z zasiegu outer()
    console.log(innerNote);  // "wewnętrzny" - z wlasnego zasiegu
  }

  inner();
}

outer();

function trzyPoziomy() {
  const a = "poziom 1";

  function poziomDrugi() {
    const b = "poziom 2";

    function poziomTrzeci() {
      const c = "poziom 3";
      console.log(a, b, c); // poziom 1 poziom 2 poziom 3
    }

    poziomTrzeci();
  }

  poziomDrugi();
}

trzyPoziomy();

function obliczSume(a, b) {
  const wynikPosredni = a + b;
  return wynikPosredni;
}

obliczSume(2, 3);
console.log(wynikPosredni); // BLEDNIE: ReferenceError - wynikPosredni nie istnieje tutaj

function obliczSume(a, b) {
  const wynikPosredni = a + b;
  return wynikPosredni;
}

const wynik = obliczSume(2, 3); // przechwycenie ZWROCONEJ wartosci
console.log(wynik); // 5 - POPRAWNIE, przez jawny return

