const nazwaFirmy = "TechCorp";

function pokazFirme() {
  console.log(nazwaFirmy);
}

pokazFirme(); // "TechCorp"

function zewnetrzna() {
  const haslo = "tajneHaslo123";

  function wewnetrzna() {
    console.log(haslo);
  }

  wewnetrzna();
}

zewnetrzna(); // "tajneHaslo123"

// wewnetrzna(); // ReferenceError: wewnetrzna is not defined
// funkcja wewnetrzna zostala zadeklarowana WEWNATRZ zewnetrzna() -
// jest wiec lokalna dla TEGO zasiegu i nie istnieje poza nim,
// dokladnie tak samo jak kazda inna zmienna lokalna funkcji

function pierwsza() {
  let licznik = 0;
  licznik++;
  licznik++;
  console.log("pierwsza:", licznik); // 2
}

function druga() {
  let licznik = 0;
  licznik++;
  console.log("druga:", licznik); // 1
}

pierwsza();
druga();

